Rpi_ZZ = PolynomialRing(ZZ, 'pi'); pi_ZZ = Rpi_ZZ.gen()

def A_series_bruteforce(coeffs, a, b, mmax):
    tot = Rpi_ZZ(_sage_const_0 )
    for ((p, q), c) in coeffs.items():
        tot += c * (_sage_const_1  + pi_ZZ)**(ZZ(p) * ZZ(a) + ZZ(q) * ZZ(b))
    return [tot[m] for m in range(mmax + _sage_const_1 )]

