def gen_pop():
    out = []
    V = [(_sage_const_1 ,_sage_const_0 ),(_sage_const_0 ,_sage_const_1 ),(_sage_const_1 ,_sage_const_1 ),(_sage_const_1 ,-_sage_const_1 ),(_sage_const_2 ,_sage_const_1 ),(_sage_const_1 ,_sage_const_2 ),(_sage_const_2 ,_sage_const_3 ),(_sage_const_0 ,_sage_const_2 ),(_sage_const_2 ,_sage_const_0 ),(_sage_const_3 ,_sage_const_1 ),(_sage_const_1 ,_sage_const_3 )]
    for r in [_sage_const_2 , _sage_const_3 ]:
        for combo in cwr(range(len(V)), r):
            out.append(('bq ' + ' '.join(str(V[i]) for i in combo), _sage_const_1 ,
                        [(_sage_const_0 , _sage_const_0 , V[i]) for i in combo]))
    for r in [_sage_const_3 , _sage_const_4 ]:
        for combo in cwr(range(len(V) + _sage_const_1 ), r):
            edges = [(_sage_const_0 , _sage_const_1 , ((_sage_const_0 , _sage_const_0 ) if i == len(V) else V[i])) for i in combo]
            out.append(('2v ' + ' '.join(('(0,0)' if i == len(V) else str(V[i]))
                                         for i in combo), _sage_const_2 , edges))
    return out

